from tastypie.resources import ModelResource
from tastypie.authentication import ApiKeyAuthentication
from tastypie.authorization import Authorization
from tastypie.exceptions import Unauthorized
from .models import CustomerBillingInvoice

class TenantScopedAuthorization(Authorization):
    def read_list(self, object_list, bundle):
        return object_list.filter(customer=bundle.request.user.customer_profile)

    def read_detail(self, object_list, bundle):
        if bundle.obj.customer != bundle.request.user.customer_profile:
            raise Unauthorized('Access denied to invoice')
        return True

class CustomerInvoiceResource(ModelResource):
    class Meta:
        queryset = CustomerBillingInvoice.objects.all()
        resource_name = 'invoices'
        authentication = ApiKeyAuthentication()
        authorization = TenantScopedAuthorization()
